import sys,re,collections,glob
per=collections.OrderedDict()
for f in sorted(glob.glob('ProjectFortress/TEST-RESULTS/system-*/TEST-*.txt')):
    cur=None
    for line in open(f,errors='replace'):
        m=re.match(r'\s*interpret \S*/tests/(\S+)',line)
        if m: cur=m.group(1); per.setdefault(cur,collections.Counter()); continue
        m=re.search(r'@@NUMEQ (\S+) (\S+)',line)
