hit={t:c for t,c in per.items() if c}
print("tests run:",len(per),"tests reaching Number's = at mixed classes:",len(hit))
pairs=collections.Counter()
for t,c in hit.items():
    for p in c: pairs[p]+=1
print("pairs (number of tests):")
for p,n in pairs.most_common(): print("  %s/%s %d"%(p[0],p[1],n))
if len(sys.argv)>1:
    for t,c in sorted(hit.items()):
        print(t, sum(c.values()), ' '.join('%s/%s:%d'%(a,b,n) for (a,b),n in c.most_common()))
EOF
